      if (!realSock || !realWriter) { lsDead152 = true; buf = new Uint8Array(0); if (waitP) { const w152 = waitP; waitP = null; w152(); } return; }   // P152: دایال مرده → بستن فوری استریم (نه سکوت ابدی و نه بلعیدن داده)
