      try { const ap = JSON.parse((await FX.store.getCore(env.DB, "ater_pool")) || "[]") || []; for (const m of ap) { if (out.length >= n) break; if (seen.has(m.ip)) continue; seen.add(m.ip); out.push(m.ip); } } catch (e) {}
