    f[0] = 0; f[1] = 4;
    f[2] = (sess >> 8) & 255; f[3] = sess & 255;
    f[4] = status; f[5] = 1;                                // opt = Data
    f[6] = (data.length >> 8) & 255; f[7] = data.length & 255;
