      const port = (meta[5] << 8) | meta[6];
      const atyp = meta[7];
      let host = "", ai = 8;
      if (atyp === 1) { if (metaLen < ai + 4) return { bad: "v4" }; host = `${meta[ai]}.${meta[ai + 1]}.${meta[ai + 2]}.${meta[ai + 3]}`; ai += 4; }
      else if (atyp === 2) { const l = meta[ai]; ai += 1; if (metaLen < ai + l) return { bad: "domain" }; host = td.decode(meta.subarray(ai, ai + l)); ai += l; }
      else if (atyp === 3) { if (metaLen < ai + 16) return { bad: "v6" }; host = b2h(meta.subarray(ai, ai + 16)); ai += 16; }
