        // return the listeners' promises so the caller can ctx.waitUntil them
        // (workerd cancels detached I/O once the originating request returns)
        const rs = [];
        for (const fn of msgFns) { try { rs.push(fn({ data })); } catch (e) {} }
        return rs.length ? Promise.allSettled(rs) : null;
