  const gcTtl = (env, k, ms) => sharedGet("core:" + k, () => FX.store.getCore(env.DB, k), ms);   /*P155:3b*/
  globalThis.__sfCorePurge = (k) => { try { sharedCache.delete("core:" + k); } catch (e) {} };   /*P155:3b — پاک‌کردن کش هستهٔ همین isolate بعد از نوشتن*/

