    if (tpathCache.v && Date.now() - tpathCache.t < 30000) return tpathCache.v;
    let p = null;
    try { p = await FX.store.getCore(env.DB, "tpath"); } catch (e) {}
    if (!p || !/^\/[a-z0-9-]{2,16}\/$/.test(p)) p = FX.BOOT.tunnelPrefix;
    tpathCache = { t: Date.now(), v: p };
