    const __nsP158 = (x) => { const m158n = /^(\d{1,3})\.(\d{1,3})\./.exec(String(x || "")); if (!m158n) return false; return (+m158n[1] === 173 && +m158n[2] === 245) || (+m158n[1] === 198 && +m158n[2] === 41); };   /*P158 — رنج‌های DNS کلادفلر: TCP زنده ولی 403 error 1034 برای workers.dev — هرگز در ساب ننشینند (173.245.58.131 رتبهٔ ۱ رادار بود!)*/
