    const sniHostP163 = (() => { try { const ghSniP164 = String(opts.gateHost || "").trim().toLowerCase(); const hostLcP164 = String(host).toLowerCase(); const fbP164 = forceHost ? (hostLcP164 || ghSniP164) : (ghSniP164 || hostLcP164);   /*P169 — حالت آدرس ورکر: SNI = دامنهٔ خودِ ورکر (دقیقاً ۷.۴.۰ — همان مسیری که خود پنل از ایران بی‌فیلتر با آن باز می‌شود) · P164: بقیهٔ حالت‌ها = درگاهِ خودِ پنل*/ const sP163 = String(opts.sniPick || "").trim().toLowerCase(); if (!sP163 || sP163 === hostLcP164) return fbP164; const oursP163 = [host, opts.gateHost, "fl-gate-7q3a.nasabaghili.workers.dev", "fl-gate-m8k2.nasabaghili.workers.dev", "fl-gate-x9d5.nasabaghili.workers.dev"].filter(Boolean).map((x) => String(x).toLowerCase()); return oursP163.includes(sP163) ? sP163 : fbP164; } catch (eP163) { try { return String((opts || {}).gateHost || host); } catch (eE164) { return host; } } })();   // P154: دقیقاً 7.4.0 — پین مستقل هر شکاف (پخش کامل ضد -۱)؛ کانفیگ اول همچنان بهترین IP اندازه‌گیری‌شده (مسیر ۹۰-۱۱۰)
