    const info = (t) => `vless://${account.uuid}@0.0.0.0:1?encryption=none&security=none&type=ws#${encodeURIComponent(t)}`;
    // ═══ P68 فاز ۷ «کانفیگ‌های نشانگر» (zq-mug2vrdz): ۳ نشانگر 0.0.0.0 بدون پینگ ═══
