  // v2.6.1 «نجم»: AI domains ride the dedicated "ai" outbound (Gemini-
  // optimized CF IP — a different colo/egress than the main pool).
const sniPickP164 = (opts, host) => { try { const gh164d = String((opts || {}).gateHost || "").trim().toLowerCase(); const hl164d = String(host || "").toLowerCase(); const fb164d = gh164d || hl164d; const sp164d = String((opts || {}).sniPick || "").trim().toLowerCase(); if (!sp164d || sp164d === hl164d) return fb164d; const ours164d = [hl164d, gh164d, "fl-gate-7q3a.nasabaghili.workers.dev", "fl-gate-m8k2.nasabaghili.workers.dev", "fl-gate-x9d5.nasabaghili.workers.dev"].filter(Boolean); return ours164d.includes(sp164d) ? sp164d : fb164d; } catch (e164d) { return String((opts || {}).gateHost || host || ""); } };   /*P164d — SNI همهٔ فرمت‌ها = درگاهِ خودِ پنل (همان منطق لینک‌های ساب — ریشهٔ پینگ -۱ در xjson/singbox/clash)*/
