  async function userDelete(request, env, uid) {
    const account = await FX.store.getAccount(env.DB, uid);
    if (!account) return bad("not-found", 404);
    await FX.store.deleteAccount(env.DB, uid);
    await FX.store.logEvent(env.DB, "user_del", account.label);
    return json({ ok: true });
  }

  async function usersBulk(request, env) {
    const _b52 = await body(request);
    if (_b52.csv !== undefined) {
      const lines = String(_b52.csv || "").split(/\r?\n/).map((l) => l.trim()).filter(Boolean);
      const created = [], errors = [];
      for (const line of lines) {
        const [name, gb, days, note] = line.split(",").map((s) => s.trim());
        try {
          const req2 = new Request("https://panel/api/users", { method: "POST", headers: { "content-type": "application/json" }, body: JSON.stringify({ label: name, gb: Number(gb) || 0, days: Number(days) || 0, note: note || "" }) });
          const r = await userCreate(req2, env);
          const j = await r.json();
          if (j && j.ok) created.push(name); else errors.push(line);
        } catch (e) { errors.push(line + ": " + e.message); }
      }
      return json({ ok: true, created: created.length, errors });
    }
    const { uids, action, days } = _b52;
    if (!Array.isArray(uids) || !uids.length || uids.length > 200) return bad("uids-required");
    let affected = 0;
    for (const uid of uids) {
      const account = await FX.store.getAccount(env.DB, uid);
      if (!account) continue;
      if (action === "delete") await FX.store.deleteAccount(env.DB, uid);
      else if (action === "pause") await FX.store.updateAccount(env.DB, uid, { status: "paused" });
      else if (action === "activate") await FX.store.updateAccount(env.DB, uid, { status: "active" });
      else if (action === "renew") {
        const d = Number(days) || 30;
        const base = account.expires_ms && account.expires_ms > Date.now() ? account.expires_ms : Date.now();
        await FX.store.updateAccount(env.DB, uid, { expires_ms: base + d * 86400000 });
      }
      affected++;
    }
    await FX.store.logEvent(env.DB, "bulk", `${action} ×${affected}`);
    return json({ ok: true, data: { affected } });
  }

  // ── plans ──
  async function plansList(env) { const _pl = await FX.store.listPlans(env.DB);
    return json({ ok: true, data: _pl, plans: _pl.map((p) => ({ id: p.pid, fa: p.label, en: p.label, days: p.days, gb: p.gb, price: p.price || "", protocols: p.protocols || "vless,trojan,ss,vmess", ports   /*P156:3*/: p.ports || "443,8443" })) }); }
  async function planSave(request, env) {
    const b = await body(request);
    if (!b.pid || !b.label) return bad("pid+label-required");
    await FX.store.upsertPlan(env.DB, { pid: String(b.pid).slice(0, 20), label: String(b.label).slice(0, 40), days: Number(b.days) || 0, gb: Number(b.gb) || 0, price: String(b.price || "").slice(0, 20), sort: Number(b.sort) || 0 });
    await FX.store.logEvent(env.DB, "plan", b.label);
    return json({ ok: true });
  }
  async function planDelete(request, env, pid) {
    await FX.store.deletePlan(env.DB, pid);
    await FX.store.logEvent(env.DB, "plan", `del ${pid}`);
    return json({ ok: true });
  }

  // ── security ──
  async function audit(env) { const _ev = await FX.store.recentEvents(env.DB, 60); return json({ ok: true, data: _ev, events: _ev }); }

  async function sessionsList(request, env, auth) {
    const { results } = await env.DB.prepare("SELECT key, value FROM settings WHERE key LIKE 'sess_%'").all();
    return json({ ok: true, data: (results || []).map((r) => ({ token: r.key.slice(5), expires: Number(r.value), current: auth.token && r.key === `sess_${auth.token}` })) });
  }
  async function sessionsKill(request, env, auth) {
    const { results } = await env.DB.prepare("SELECT key FROM settings WHERE key LIKE 'sess_%'").all();
    const stmts = (results || []).filter((r) => !auth.token || r.k !== `sess_${auth.token}`).map((r) => env.DB.prepare("DELETE FROM settings WHERE key=?").bind(r.key));
    if (stmts.length) await env.DB.batch(stmts);
    await FX.store.logEvent(env.DB, "session", `killed ${stmts.length}`);
    return json({ ok: true });
  }

  async function passwordChange(request, env) {
    const { current, next } = await body(request);
    const hash = await coreGet(env, "passwd_hash");
    if (!(await FX.crypto.verifyPassword(String(current || ""), hash))) return bad("bad-password", 401);
    if (String(next || "").length < 6) return bad("short-password");
    await coreSet(env, "passwd_hash", await FX.crypto.hashPassword(next));
    await FX.store.logEvent(env.DB, "pw", "change");
    return json({ ok: true });
  }

  async function twofaSetup(request, env) {
    const secret = FX.crypto.newTotpSecret();
    await coreSet(env, "totp_pending", secret);
    const host = new URL(request.url).host;
    const otpauth = `otpauth://totp/FLASH:${encodeURIComponent(host)}?secret=${secret}&issuer=FLASH&algorithm=SHA1&digits=6&period=30`;
    return json({ ok: true, data: { secret, otpauth } });
  }
  async function twofaEnable(request, env) {
    const { code } = await body(request);
    const secret = await coreGet(env, "totp_pending");
    if (!secret) return bad("no-pending");
    if (!(await FX.crypto.totpVerify(secret, code))) return bad("bad-code");
    await coreSet(env, "totp_secret", secret);
    await coreSet(env, "totp_on", "1");
    await coreSet(env, "totp_pending", "");
    await FX.store.logEvent(env.DB, "2fa", "on");
    return json({ ok: true });
  }
  async function twofaDisable(request, env) {
    const { code } = await body(request);
    const secret = await coreGet(env, "totp_secret");
    if (!secret || (await coreGet(env, "totp_on")) !== "1") return bad("not-on");
    if (!(await FX.crypto.totpVerify(secret, code))) return bad("bad-code");
    await coreSet(env, "totp_on", "0");
    await FX.store.logEvent(env.DB, "2fa", "off");
    return json({ ok: true });
  }

  async function botKey(request, env) {
    if (request.method === "POST") {
      if (env.BOTKEY) return json({ ok: true, data: { key: env.BOTKEY, fixed: true } });
      const key = FX.crypto.newBotKey();
      await coreSet(env, "botkey", key);
      await FX.store.logEvent(env.DB, "botkey", "regen");
      return json({ ok: true, data: { key } });
    }
    return json({ ok: true, data: { key: (await coreGet(env, "botkey")) || env.BOTKEY || "" } });
  }

  // ── per-user individual config links (v2.2: proto/port/loc-aware) ──
  async function userLinks(request, env, uid) {
    const account = await FX.store.getAccount(env.DB, uid);
    if (!account) return bad("not-found", 404);
    const shards = await FX.subx.linksFor(env, account, new URL(request.url).hostname, { lite: 1 });
    return json({ ok: true, data: shards.map((s) => ({ k: s.k, proto: s.proto, port: s.port, tls: s.tls, cc: s.cc || "", duty: s.duty || "", icon: s.icon || "", link: s.link })) });
  }


  // ── SUPER FLASH telemetry (v2.0) ──
  
  // ── SUPER FLASH v3.0 · P58 — معماری سوپر هسته (فاز ۱) ──
  
  // ── P62: دریافت متریک انتقال واقعی از ربات‌ها (botkey-authed) ──
  async function sfTelemetryPost(request, env) {
    const auth = await requireAuth(request, env);
    if (!auth.ok) return json({ ok: false, error: "unauthorized" }, 401);
    const b = await body(request);
    const r = await SF.SUPER.TG.ingest(env, b);
    if (!r.ok) return json({ ok: false, error: r.error }, 400);
    return json({ ok: true });
  }

async function sfSuperGet(request, env) {
    await SF.hydrate(env.DB);
    let host = null;
    try { host = new URL(request.url).host; } catch (e) {}
    if (host) { try { await SF.SUPER.saveState(env.DB, "panel_host", host); } catch (e) {} }   // P60: میزبان واقعی پنل برای چرخهٔ ورکر
    const snap = SF.SUPER.snapshot();
    const targets = await SF.SUPER.configTargets(env, host);
    const caps = SF.SUPER.capabilityReport();
    let learning = null;
    let candidates = null;
    let universal = null;
    let trafficServices = null;
    let configs = null;
    let decisions = null;
    try { decisions = await SF.SUPER.DEC.decisionReport(env); } catch (e) {}
    try { configs = await SF.SUPER.CIQ.report(env); } catch (e) {}
    try { trafficServices = await SF.SUPER.SVCU.report(env); } catch (e) {}
    try { universal = await SF.SUPER.UNI.report(env, host); } catch (e) {}
    let geoR = null;
    try { geoR = await SF.SUPER.GEO.report(env); } catch (e) {}
    let tgdcR = null;
    try { tgdcR = SF.SUPER.TGD.report(env); } catch (e) {}
    let mega = null;
    try { mega = await SF.SUPER.MEGA.strategy(env); } catch (e) {}   // P68 فاز ۵: مگا-سوپر روش
    let orchestrator = null;
    let telegram = null;
    let serviceStrategies = null;
    let speed = null;
    try { speed = await SF.SUPER.SPEED.report(env); } catch (e) {}
    try { serviceStrategies = await SF.SUPER.SVC.report(env); } catch (e) {}
    try { telegram = await SF.SUPER.TG.report(env); } catch (e) {}
    try { orchestrator = SF.SUPER.ORT.report(); } catch (e) {}
    try { let whost = null; try { whost = new URL(request.url).host; } catch (e) {} candidates = await SF.SUPER.CAND.report(env, whost); } catch (e) {}
    try { learning = await SF.SUPER.LEARN.learningReport(env.DB); } catch (e) {}
    const engines = SF.SUPER.ENGINE_FAMILIES.map((f) => ({ id: f.id, fa: f.fa, engines: f.engines.map((e) => ({ id: e.id, fa: e.fa, st: e.st, d: e.d })) }));
    let lastCycle = null;
    try { lastCycle = await SF.SUPER.loadState(env.DB, "last_cycle", null); } catch (e) {}
    return json({ ok: true, data: { ...snap, engines, learning, candidates, universal, geo: geoR, routeApply: (globalThis.SF && globalThis.SF.SUPER && globalThis.SF.SUPER.RTX) ? SF.SUPER.RTX.statsReport() : null, tgdc: tgdcR, mega, trafficServices, configs, decisions, orchestrator, telegram, serviceStrategies, speed, capabilities: caps, configTargets: targets, lastCycle, honestNote: "وضعیت هر موتور/هسته صادقانه است: live = مکانیزم واقعی فعال · pXX = فاز ساخت این پروژه. هیچ دادهٔ جعلی وجود ندارد." } });
  }

async function sfApi(request, env) {
    await SF.hydrate(env.DB);
    const u = new URL(request.url);
    const snap = SF.snapshot(u.searchParams.get("deep") === "1");
    if (u.searchParams.get("history") === "1") {
      let events = [];
      try {
        const r = await env.DB.prepare("SELECT ts, kind, detail FROM sf_events ORDER BY ts DESC LIMIT 60").all();
        events = (r && r.results) || [];
      } catch (e) {}
      return json({ ok: true, data: { snapshot: snap, events } });
    }
    return json({ ok: true, data: { snapshot: snap } });
  }

  // ── SUPER FLASH orchestrator endpoints (v2.0 فاز ۳) ──
  async function sfCycleGet(env) {
    await SF.hydrate(env.DB);
    let best = null;
    try { best = JSON.parse((await coreGet(env, "sf_dns_best")) || "null"); } catch (e) {}
    return json({ ok: true, data: { lastCycle: { at: SF.NET.lastCycleAt, ms: SF.NET.lastCycleMs, steps: SF.NET.lastCycleSteps, cycles: SF.NET.cycles }, dnsBest: best, bench: SF.BENCH.current, runs: SF.BENCH.runs.slice(-6) } });
  }
  async function sfCyclePost(request, env) {
    await SF.hydrate(env.DB);
    let kind = "full", force = false;
    try { const b = await request.json(); if (b && b.kind) kind = String(b.kind); if (b && b.force === true) force = true; } catch (e) {}
    if (["dns", "services", "endpoints", "full"].indexOf(kind) < 0) return bad("kind-invalid");
    const r = await SF.runCycle(env, { kind, source: "admin", force });
    if (r && r.ok === false && r.error === "rate-limited") return json({ ok: false, error: "rate-limited", retryInMs: r.retryInMs }, 429);
    return json({ ok: !!(r && r.ok), data: r });
  }

  // ── SUPER FLASH focused benchmark (فاز ۴ — LATENCY/PING/JITTER/LOSS عمیق) ──
  async function sfBenchmarkPost(request, env) {
    await SF.hydrate(env.DB);
    let target = null, probes = 5, kindParam = null;
    try { const b = await request.json(); target = String(b.target || ""); if (b.probes) probes = Math.max(2, Math.min(8, Number(b.probes) || 5)); if (b.kind) kindParam = String(b.kind); } catch (e) {}

    // ═══ فاز ۱۱ — RANGE SWEEP واقعی: ۲ IP از هر /24 آتر/WARP → liveness + RTT + jitter + loss ═══
    if (kindParam === "ranges") {
      const ranges = FX.ATER_RANGES || [];
      const perRange = 2;                            // ۲ IP از هر رنج، هرکدام ۱ probe → ۲ نمونه/رنج = jitter واقعی
      const need = ranges.length * perRange;         // ۲۶ subrequest — زیر سقف ۴۲
      SF.budgetReset();
      if (!SF.budgetTake(ranges.length, need)) return json({ ok: false, error: "budget" }, 429);
      const results = [];
      for (let ri = 0; ri < ranges.length; ri++) {
        const cidr = ranges[ri];
        const [base, pre] = cidr.split("/");
        const oct = base.split(".").map(Number);
        const ips = [];
        for (let k = 0; k < perRange; k++) {
          const ip = [oct[0], oct[1], oct[2], 1 + Math.floor(Math.random() * 254)].join(".");
          ips.push(ip);
        }
        const prs = await Promise.all(ips.map(async (ip) => {
          const a = await SF.probeTcp(ip, 443, 3000).catch(() => ({ ok: false, ms: 0 }));
          return { ip, a };
        }));
        const okRtts = prs.filter(p => p.a.ok).map(p => p.a.ms);
        const lossPct = +((1 - (okRtts.length / perRange)) * 100).toFixed(1);
        const minMs = okRtts.length ? Math.min.apply(null, okRtts) : null;
        const avgMs = okRtts.length ? Math.round(okRtts.reduce((x, y) => x + y, 0) / okRtts.length) : null;
        let jit = 0;
        if (okRtts.length >= 2) { const s = okRtts.slice().sort((x, y) => x - y); jit = Math.abs(s[s.length - 1] - s[0]); }
        const cls = cidr.startsWith("162.159.19") ? "warp-ingress" : cidr.startsWith("188.114.") ? "workers" : "edge";
        const sc = SF.scoreObserve("range:" + cidr, "range", avgMs, jit, lossPct);
        if (okRtts.length) SF.healthMarkOk("range:" + cidr); else SF.healthMarkFail("range:" + cidr);
        results.push({ cidr, cls, probedIps: ips, alive: okRtts.length > 0, aliveProbes: okRtts.length + "/" + perRange, minMs, avgMs, jitterMs: jit, lossPct, score: sc.score });
      }
      await SF.persist(env.DB, 40);
      await SF.logEvent(env.DB, "benchmark", "ranges " + results.filter(r => r.alive).length + "/" + results.length + " alive");
      return json({ ok: true, data: { kind: "ranges", vantage: "worker-tcp", results, alive: results.filter(r => r.alive).length + "/" + results.length } });
    }

    // ═══ فاز ۱۵ — AI ACCESS BENCHMARK: probe واقعی همهٔ endpointهای AI/LLM ═══
    if (kindParam === "ai") {
      const aiSvcs = SF.DISC.services.filter((s) => s.cat === "ai");
      const probesPer = 3;
      const need = aiSvcs.length * probesPer;
      SF.budgetReset();
      if (!SF.budgetTake(aiSvcs.length, need)) return json({ ok: false, error: "budget" }, 429);
      const results = [];
      for (let i = 0; i < aiSvcs.length; i += 2) {
        const batch = aiSvcs.slice(i, i + 2);
        const rs = await Promise.all(batch.map(async (s) => {
          const probes = [];
          for (let p = 0; p < probesPer; p++) {
            probes.push(await SF.probeFetch(s.url, s.method).catch(() => ({ ok: false, status: 0, ms: 9999, ttfbMs: null, error: "throw" })));
          }
          return { s, probes };
        }));
        for (const { s, probes } of rs) {
          const oks = probes.filter(p => p.ok);
          const rtts = oks.map(p => p.ms);
          const ttfbs = oks.map(p => p.ttfbMs).filter(v => v != null);
          const lossPct = +(((probes.length - oks.length) / probes.length) * 100).toFixed(1);
          const avg = rtts.length ? Math.round(rtts.reduce((a, b) => a + b, 0) / rtts.length) : null;
          let jit = 0;
          if (rtts.length >= 2) { const so = rtts.slice().sort((a, b) => a - b); jit = so[so.length - 1] - so[0]; }
          const key = "svc:" + s.id;
          const sc = SF.scoreObserve(key, "service", avg, jit, lossPct);
          if (oks.length) SF.healthMarkOk(key); else SF.healthMarkFail(key);
          results.push({
            id: s.id, alive: oks.length > 0, aliveProbes: oks.length + "/" + probes.length,
            latencyMs: avg, ttfbMs: ttfbs.length ? Math.round(ttfbs.reduce((a, b) => a + b, 0) / ttfbs.length) : null,
            jitterMs: jit, lossPct, status: probes.map(p => p.status).find(x => x > 0) || 0,
            score: sc.score, consistent: SF.SEC.consistent(probes.map(p => p.status)),
          });
        }
      }
      await SF.persist(env.DB, 40);
      await SF.logEvent(env.DB, "benchmark", "ai " + results.filter(r => r.alive).length + "/" + results.length + " alive");
      return json({ ok: true, data: { kind: "ai", vantage: "worker-egress", results, alive: results.filter(r => r.alive).length + "/" + results.length } });
    }

    // ═══ فاز ۱۲-۱۳ — THROUGHPUT واقعی: دانلود ۴MB + آپلود ۱MB از مسیر خود ورکر ═══
    if (kindParam === "throughput") {
      // نرخ‌محور: حداکثر هر ۵ دقیقه (پهنای‌باند و CPU واقعی مصرف می‌شود)
      if (Date.now() - (globalThis.__sfThrAt || 0) < 300000) return json({ ok: false, error: "rate-limited", retryInMs: 300000 - (Date.now() - (globalThis.__sfThrAt || 0)) }, 429);
      globalThis.__sfThrAt = Date.now();
      SF.budgetReset();
      if (!SF.budgetTake(2, 2)) return json({ ok: false, error: "budget" }, 429);
      const down = await SF.probeThroughput(4 * 1024 * 1024, "down");
      const up = await SF.probeThroughput(1024 * 1024, "up");
      const downScore = SF.thrScore(down.mbs), upScore = SF.thrScore(up.mbs);
      const rec = { at: Date.now(), vantage: "worker-egress (مسیر خود ورکر — سرعت واقعی کاربر از تونل، سمت کاربر اندازه‌گیری می‌شود)", down: { mbs: down.mbs, bytes: down.bytes, secs: down.secs, ttfbMs: down.ttfbMs != null ? down.ttfbMs : null, ok: down.ok, error: down.error }, up: { mbs: up.mbs, bytes: up.bytes, secs: up.secs, ok: up.ok, error: up.error }, downScore, upScore };
      SF.BENCH.throughput = rec;
      SF.BENCH.runs.push({ at: Date.now(), kind: "throughput", source: "admin", down: down.mbs, up: up.mbs });
      if (SF.BENCH.runs.length > 12) SF.BENCH.runs.shift();
      if (down.mbs != null) SF.SCORES.set("thr:down", { type: "throughput", score: downScore, latency: null, jitter: null, loss: null, n: 1, hist: [{ t: Date.now(), lat: null, jit: null, loss: down.mbs }], updatedAt: Date.now() });
      if (up.mbs != null) SF.SCORES.set("thr:up", { type: "throughput", score: upScore, latency: null, jitter: null, loss: null, n: 1, hist: [{ t: Date.now(), lat: null, jit: null, loss: up.mbs }], updatedAt: Date.now() });
      await SF.logEvent(env.DB, "benchmark", "throughput down=" + down.mbs + "MB/s up=" + up.mbs + "MB/s");
      return json({ ok: true, data: rec });
    }

    if (!/^(dns|svc):[a-z0-9-]+$/.test(target)) return bad("target-invalid");
    const [kind, id] = target.split(":");
    let url = null, isDoh = false;
    if (kind === "dns") {
      const r = SF.DISC.dnsResolvers.find((x) => x.id === id);
      if (r) { url = r; isDoh = true; }
    } else {
      const s = SF.DISC.services.find((x) => x.id === id);
      if (s) url = { url: s.url, method: s.method };
    }
    if (!url) return bad("target-unknown");
    if (!SF.budgetTake(1, probes)) return json({ ok: false, error: "budget" }, 429);
    SF.budgetReset(); SF.budgetTake(1, probes);   // focused bench = own budget scope
    const t0 = Date.now();
    const pr = [];
    for (let i = 0; i < probes; i++) {
      pr.push(isDoh ? SF.probeDoh(url) : SF.probeFetch(url.url, url.method));
    }
    const raw = await Promise.all(pr);
    const okOnes = raw.filter(p => p.ok);
    const rtts = okOnes.map(p => p.ms);
    const ttfbs = okOnes.map(p => p.ttfbMs).filter(v => v != null);
    const stats = {
      target, probes, at: Date.now(), benchMs: Math.round(performance.now() - t0),
      alive: okOnes.length + "/" + probes,
      rtt: rtts.length ? { min: Math.min.apply(null, rtts), avg: Math.round(rtts.reduce((a, b) => a + b, 0) / rtts.length), max: Math.max.apply(null, rtts), values: rtts } : null,
      ttfb: ttfbs.length ? { min: Math.min.apply(null, ttfbs), avg: Math.round(ttfbs.reduce((a, b) => a + b, 0) / ttfbs.length), max: Math.max.apply(null, ttfbs) } : null,
      errors: raw.map(p => p.error).filter(Boolean),
    };
    // observe into the adaptive engine (jitter از اختلاف متوالی)
    let prev = null, jsum = 0, jn = 0;
    for (const v of rtts) { if (prev != null) { jsum += Math.abs(v - prev); jn++; } prev = v; }
    const jit = jn ? Math.round(jsum / jn) : 0;
    const lossPct = +(((probes - okOnes.length) / probes) * 100).toFixed(1);
    const avg = rtts.length ? rtts.reduce((a, b) => a + b, 0) / rtts.length : null;
    const sc = SF.scoreObserve(target, kind === "dns" ? "dns" : "service", avg, jit, lossPct);
    if (okOnes.length) SF.healthMarkOk(target); else SF.healthMarkFail(target);
    await SF.persist(env.DB, 40);
    await SF.logEvent(env.DB, "benchmark", target + " alive=" + stats.alive + (stats.rtt ? " avg=" + stats.rtt.avg + "ms" : "") + (stats.ttfb ? " ttfb=" + stats.ttfb.avg + "ms" : ""));
    return json({ ok: true, data: { stats, score: sc.score, deep: SF.deepStats(target) } });
  }

  // ── SUPER FLASH ROUTE ENGINE (فاز ۵) — جدول مسیرهای زنده با امتیاز چندمعیاره ──
  async function sfRoutesGet(env) {
    await SF.hydrate(env.DB);
    let pool = [];
    try { pool = JSON.parse((await coreGet(env, "ater_pool")) || "[]") || []; } catch (e) {}
    const routes = pool.map((p) => {
      const dims = { lat: p.ms, jit: p.jit != null ? p.jit : null, loss: p.loss != null ? p.loss : null, avail: p.loss != null ? 100 - p.loss : null };
      const scores = {};
      for (const prof of Object.keys(SF.PROFILES)) scores[prof] = SF.routeScore(dims, prof);
      return { ip: p.ip, ms: p.ms, jitterMs: p.jit != null ? p.jit : null, lossPct: p.loss != null ? p.loss : null, score: p.score != null ? p.score : scores.default, scores };
    });
    let meta = null;
    try { meta = JSON.parse((await coreGet(env, "ater_meta")) || "null"); } catch (e) {}
    let relayRows = [];
    try {
      const rs = JSON.parse((await coreGet(env, "relay_state")) || "{}");
      for (const [cc, arr] of Object.entries(rs)) {
        if (Array.isArray(arr) && arr.length) {
          relayRows.push({ cc, relays: arr.length, bestMs: Math.min.apply(null, arr.map((x) => Number(x.ms != null ? x.ms : 9999)).filter((v) => v < 9000).concat([null]).filter((v) => v != null))[0] ?? null });
        }
      }
    } catch (e) {}
    return json({ ok: true, data: {
      entryChain: ["dedicated", "ater-pool", "radar-spread", "ip-override", "worker-host"],
      routes, meta, relays: relayRows.slice(0, 40),
      antiPingPong: { scoreSwitchDelta: SF.CFG.scoreSwitchDelta, minHoldMs: SF.CFG.minHoldMs, cooldownMs: SF.CFG.cooldownMs, clientSide: "FL-AUTO urltest (tolerance 75ms) + fl-auto urltest (interrupt)" },
    } });
  }

  // ── SUPER FLASH RELAY VIEW (فاز ۶) — کشف جهانی + ریسینگ + سلامت، یکجا ──
  async function sfRelaysGet(env) {
    await SF.hydrate(env.DB);
    let state = {};
    try { state = JSON.parse((await coreGet(env, "relay_state")) || "{}") || {}; } catch (e) {}
    let catalog = [];
    try { catalog = await FX.proto.locCatalog(env); } catch (e) {}
    const countries = catalog.map((c) => {
      const st = state[c.id];
      const relayRows = [];
      if (st && Array.isArray(st)) {
        for (const r of st) relayRows.push({ host: r.host || r, ms: r.ms != null ? r.ms : null, verified: !!r.exit || !!r.verified });
      } else if (st && st.host) {
        relayRows.push({ host: st.host, ms: st.ms != null ? st.ms : null, verified: !!(st.exit || st.verified) });
      }
      return { cc: c.id, flag: c.flag || "", fa: c.fa || c.id, static: !!(c.static), relays: relayRows.length, best: relayRows.filter(r => r.ms != null).sort((a, b) => a.ms - b.ms)[0] || null, verified: relayRows.filter(r => r.verified).length };
    });
    // SF-scored relays (observed by real probes)
    const relayScores = SF.SCORES.size ? [...SF.SCORES.entries()].filter(([k]) => k.startsWith("relay:")).map(([k, v]) => ({
      host: k.slice(6), score: v.score, latencyMs: v.latency == null ? null : Math.round(v.latency), jitterMs: v.jitter == null ? null : Math.round(v.jitter), lossPct: v.loss == null ? null : +(v.loss.toFixed(1)), samples: v.n, state: SF.healthOf(k),
    })) : [];
    return json({ ok: true, data: {
      countries: countries.filter((c) => c.relays > 0).slice(0, 60),
      totalCountries: catalog.length,
      activeCountries: countries.filter((c) => c.relays > 0).length,
      scoredRelays: relayScores.slice(0, 40),
      circuitBreaker: { failLimit: SF.CFG.cbFailLimit, quarantineMs: SF.CFG.cbQuarantineMs, quarantined: relayScores.filter((r) => r.state === "quarantine").length },
      discovery: {
        family: "cmliussss.net per-country (verified real)",
        sources: ["ipdb public lists (geo-resolved, TCP-verified)", "static catalog", "admin manual add"],
        traps: "zeabur/ddns-ip/workers.dev wildcard traps — never enter the pool",
        racing: "raceDialVerified — staggered parallel dials ordered by measured health (v2.12)",
        cron: "relaySweepWave + 2-country discoverCountryRelaysSF per 15-min tick",
      },
    } });
  }

  // ═══ P120 «مرکز فرماندهی» — Audit + Versions + Search + Command ═══
  async function auditLog(env, actor, action, target, result, meta) {
    try {
      await env.DB.prepare("INSERT INTO audit_log (at, actor, action, target, result, meta) VALUES (?,?,?,?,?,?)")
        .bind(Date.now(), String(actor || "system").slice(0, 64), String(action || "").slice(0, 64), String(target || "").slice(0, 160), String(result || "ok").slice(0, 24), JSON.stringify(meta || null).slice(0, 2000)).run();
      try { await env.DB.prepare("DELETE FROM audit_log WHERE id <= (SELECT MAX(id) - 500 FROM audit_log)").run(); } catch (e) {}
    } catch (e) {}
  }
  async function snapshotConfig(env, note) {
    try {
      const rows = await env.DB.prepare("SELECT key, value FROM settings").all();
      const snap = {};
      for (const r of rows.results || []) snap[r.key] = r.value;
      const json = JSON.stringify(snap);
      const hash = [...new Uint8Array(await crypto.subtle.digest("SHA-256", new TextEncoder().encode(json)))].map((b) => b.toString(16).padStart(2, "0")).join("");
      const last = await env.DB.prepare("SELECT id, hash, json FROM config_versions ORDER BY id DESC LIMIT 1").first();
      if (last && last.hash === hash) return null;   // بدون تغییر — نسخهٔ جدید نمی‌سازد
      let diff = null;
      if (last) {
        const prev = JSON.parse(last.json || "{}");
        const d = [];
        for (const k of new Set([...Object.keys(prev), ...Object.keys(snap)])) {
          if (!(k in prev)) d.push("+" + k);
          else if (!(k in snap)) d.push("-" + k);
          else if (String(prev[k]) !== String(snap[k])) d.push("~" + k + ": " + String(prev[k]).slice(0, 40) + " → " + String(snap[k]).slice(0, 40));
        }
        diff = d.slice(0, 40).join(" | ");
      }
      await env.DB.prepare("INSERT INTO config_versions (at, kind, hash, json, diff, author, note) VALUES (?,?,?,?,?,?,?)")
        .bind(Date.now(), "settings", hash, json, diff, "panel", String(note || "").slice(0, 120)).run();
      try { await env.DB.prepare("DELETE FROM config_versions WHERE id <= (SELECT MAX(id) - 30 FROM config_versions)").run(); } catch (e) {}
      return { hash: hash.slice(0, 12), changed: diff ? diff.split(" | ").length : null };
    } catch (e) { return null; }
  }
  // نمای یک‌نگاه: سیستم + اندپوینت + رله + قطع‌کننده + کاربر + ترافیک + رویداد
  async function sfCmdGet(env) {
    await FX.BREAKER.hydrate(env);
    const out = { version: FX.BOOT.version, core: FX.BOOT.core, now: Date.now() };
    try { const r = await env.DB.prepare("SELECT COUNT(*) c, SUM(CASE WHEN is_active=1 THEN 1 ELSE 0 END) a FROM users").first(); out.users = { total: r.c, active: r.a }; } catch (e) { out.users = { total: 0, active: 0 }; }
    try { const r = await env.DB.prepare("SELECT SUM(used_gb) g FROM users").first(); out.trafficGb = +(r.g || 0).toFixed(2); } catch (e) { out.trafficGb = 0; }
    try { const pool = JSON.parse((await FX.store.getCore(env.DB, "ater_pool")) || "[]") || []; out.endpoints = { pool: pool.length }; } catch (e) { out.endpoints = { pool: 0 }; }
    try { const st = await FX.proto.relayStateGet(env); const relays = Object.entries(st || {}).filter(([, v]) => v && v.host); out.relays = { live: relays.filter(([, v]) => v.ms > 0).length, total: relays.length, best: relays.sort((a, b) => (a[1].ms || 9e9) - (b[1].ms || 9e9)).slice(0, 3).map(([cc, v]) => ({ cc, host: v.host, ms: v.ms })) }; } catch (e) { out.relays = { live: 0, total: 0 }; }
    out.breaker = FX.BREAKER.summary();
    try { const r = await env.DB.prepare("SELECT id, at, actor, action, target, result FROM audit_log ORDER BY id DESC LIMIT 8").all(); out.recentAudit = r.results || []; } catch (e) { out.recentAudit = []; }
    try { const r = await env.DB.prepare("SELECT id, at, hash, diff, note FROM config_versions ORDER BY id DESC LIMIT 5").all(); out.versions = r.results || []; } catch (e) { out.versions = []; }
    try { const r = await env.DB.prepare("SELECT ts, kind, detail FROM sf_events ORDER BY id DESC LIMIT 8").all(); out.events = r.results || []; } catch (e) { out.events = []; }
    return json({ ok: true, data: out });
  }
  // جستجوی سراسری: کاربر + اندپوینت + رله + رویداد + تنظیمات
  async function sfSearchGet(request, env) {
    const q = ((new URL(request.url)).searchParams.get("q") || "").trim().toLowerCase();
    if (q.length < 2) return json({ ok: true, data: { q, users: [], endpoints: [], relays: [], audit: [], settings: [] } });
    const like = "%" + q.replace(/[%_]/g, "") + "%";
    const out = { q };
    try { const r = await env.DB.prepare("SELECT id, username, uid, is_active, used_gb, limit_gb FROM users WHERE LOWER(username) LIKE ? OR LOWER(uuid) LIKE ? OR CAST(id AS TEXT) = ? OR uid LIKE ? LIMIT 12").bind(like, like, q.replace(/[^0-9]/g, "") || "-1", like).all(); out.users = r.results || []; } catch (e) { out.users = []; }
    try {
      const pool = JSON.parse((await FX.store.getCore(env.DB, "ater_pool")) || "[]") || [];
      out.endpoints = pool.filter((p) => p && String(p.ip).includes(q)).slice(0, 12).map((p) => ({ ip: p.ip, ms: p.ms }));
    } catch (e) { out.endpoints = []; }
    try {
      const st = await FX.proto.relayStateGet(env) || {};
      out.relays = Object.entries(st).filter(([cc, v]) => v && v.host && (String(v.host).toLowerCase().includes(q) || cc.includes(q))).slice(0, 12).map(([cc, v]) => ({ cc, host: v.host, ms: v.ms }));
    } catch (e) { out.relays = []; }
    try { const r = await env.DB.prepare("SELECT id, at, actor, action, target, result FROM audit_log WHERE LOWER(action) LIKE ? OR LOWER(target) LIKE ? ORDER BY id DESC LIMIT 12").bind(like, like).all(); out.audit = r.results || []; } catch (e) { out.audit = []; }
    try { const r = await env.DB.prepare("SELECT key, value FROM settings WHERE LOWER(key) LIKE ? LIMIT 12").bind(like).all(); out.settings = (r.results || []).map((x) => ({ key: x.key, value: String(x.value).slice(0, 40) })); } catch (e) { out.settings = []; }
    return json({ ok: true, data: out });
  }
  async function sfAuditGet(request, env) {
    const limit = Math.min(Number((new URL(request.url)).searchParams.get("limit")) || 60, 200);
    try { const r = await env.DB.prepare("SELECT id, at, actor, action, target, result, meta FROM audit_log ORDER BY id DESC LIMIT ?").bind(limit).all(); return json({ ok: true, data: r.results || [] }); }
    catch (e) { return json({ ok: true, data: [] }); }
  }
  async function sfVersionsGet(request, env) {
    try { const r = await env.DB.prepare("SELECT id, at, kind, hash, diff, author, note FROM config_versions ORDER BY id DESC LIMIT 40").all(); return json({ ok: true, data: r.results || [] }); }
    catch (e) { return json({ ok: true, data: [] }); }
  }
  async function sfVersionsRollback(request, env) {
    const b = await body(request);
    const id = Number(b && b.id);
    if (!id) return json({ ok: false, error: "id" }, 400);
    try {
      const v = await env.DB.prepare("SELECT json FROM config_versions WHERE id=?").bind(id).first();
      if (!v || !v.json) return json({ ok: false, error: "not-found" }, 404);
      const snap = JSON.parse(v.json);
      for (const [k, val] of Object.entries(snap)) await FX.store.setCore(env.DB, k, val);
      await auditLog(env, "panel", "config.rollback", "version#" + id, "ok", { keys: Object.keys(snap).length });
      const snap2 = await snapshotConfig(env, "rollback→#" + id);
      return json({ ok: true, data: { restored: Object.keys(snap).length, snapshot: snap2 } });
    } catch (e) { return json({ ok: false, error: String(e.message || e) }, 500); }
  }

  // ── SUPER FLASH ENDPOINT ENGINE (فاز ۷) — نمای اندپوینت‌های ورودی ──
  async function sfEndpointsGet(env) {
    await SF.hydrate(env.DB);
    let pool = [], meta = null;
    try { pool = JSON.parse((await coreGet(env, "ater_pool")) || "[]") || []; } catch (e) {}
    try { meta = JSON.parse((await coreGet(env, "ater_meta")) || "null"); } catch (e) {}
    const staleHours = meta && meta.at ? Math.round((Date.now() - meta.at) / 3600000) : null;
    const endpoints = pool.map((p) => {
      const key = "ep:" + p.ip;
      const sc = SF.SCORES.get(key);
      return {
        ip: p.ip, lane: "entry+game",
        client: { ms: p.ms, jitterMs: p.jit != null ? p.jit : null, lossPct: p.loss != null ? p.loss : null, score: p.score != null ? p.score : null },
        learned: sc ? { ewmaLatencyMs: sc.latency == null ? null : Math.round(sc.latency), ewmaJitterMs: sc.jitter == null ? null : Math.round(sc.jitter), ewmaLossPct: sc.loss == null ? null : +(sc.loss.toFixed(1)), samples: sc.n, deep: SF.deepStats(key) } : null,
        liveness: SF.healthOf(key),
        inCfRanges: (() => { try { return FX.aterIpOk(p.ip); } catch (e) { return null; } })(),
      };
    });
    // candidates universe
    let candCount = 0, warpShare = null;
    try {
      const c = FX.aterSample(200);
      candCount = c.length;
      warpShare = c.filter((ip) => ip.startsWith("162.159.19")).length / (c.length || 1);
    } catch (e) {}
    return json({ ok: true, data: {
      endpoints, meta, staleHours,
      recommendation: staleHours != null && staleHours >= 24 ? "rescan-recommended" : "fresh",
      candidates: { sampleSize: candCount, warpShare: warpShare != null ? +(warpShare.toFixed(2)) : null, ranges: "13 verified /24s (WARP ingress 162.159.192-199 · workers 188.114.96-99 · edge 104.24-27)" },
      failover: { clientSide: "FL-AUTO urltest 180s/60ms + fl-auto urltest 3m/75ms interrupt", serverSide: "pool re-scored on every scan; multi-criteria order" },
    } });
  }

