    if (path === "/api/tunnel/auto-ob" && method === "POST") return tunnelAutoOb(request, env);   // P78 فاز ۵
    if (path === "/api/stats" && method === "GET") return stats(env, new URL(request.url));   // P157:1 — live=1: مسیر سبک چارت ثانیه‌ای
    if (path === "/api/users" && method === "GET") return usersList(request, env);
    if (path === "/api/users" && method === "POST") return userCreate(request, env);
    if (path === "/api/users/bulk" && method === "POST") return usersBulk(request, env);
