export default {
  async fetch(request, env, ctx) {
    try { globalThis.__p178ctx = ctx; } catch (eC178) {}   // P178: ctx برای نوشتن gem_last_good (waitUntil)
    /* ═══ P170-Q1 «سپر سهمیه» — خطای D1 هرگز به Error 1101 کلادفلر نمی‌رسد ═══ */
    try { return await FX.router.handle(request, env, ctx); }
    catch (e) {
      const msg = String((e && e.message) || e);
      if (/quota|exceeded|daily limit|row read|row write|too many requests/i.test(msg)) {
        const resetIso = new Date(Math.ceil(Date.now() / 86400000) * 86400000).toISOString();
        const isApi = new URL(request.url).pathname.startsWith("/api/");
        if (isApi) return new Response(JSON.stringify({ ok: false, error: "d1-quota", resetAt: resetIso, note: "سهمیهٔ روزانهٔ D1 تمام شده — نیمه‌شب UTC بازنشانی می‌شود" }), { status: 200, headers: { "content-type": "application/json; charset=utf-8", "cache-control": "no-store" } });
        return new Response("Service temporarily unavailable (daily quota); retry after " + resetIso, { status: 503, headers: { "retry-after": "3600", "content-type": "text/plain; charset=utf-8" } });
      }
      throw e;
    }
  },
  async scheduled(event, env, ctx) { return FX.router.cron(event, env, ctx); },
};


